-- Additive only. Seven undated-year rows remain explicitly provisional.
CREATE TABLE crm_exhibitions (
 id TEXT PRIMARY KEY NOT NULL,
 data TEXT NOT NULL CHECK(json_valid(data)),
 version INTEGER NOT NULL DEFAULT 1,
 created TEXT NOT NULL,
 updated TEXT NOT NULL,
 updated_by TEXT REFERENCES crm_users(id)
);
CREATE TABLE crm_exhibition_deals (
 deal_id TEXT PRIMARY KEY NOT NULL REFERENCES crm_deals(id),
 exhibition_id TEXT NOT NULL REFERENCES crm_exhibitions(id)
);
CREATE INDEX crm_exhibition_deals_show ON crm_exhibition_deals(exhibition_id);
